#!name=联通余量(v4)
#!author=queitstart pro
#!date=2026-11-21
#!desc=定时查询, Panel 面板, 抓包
#!arguments=cronexp:*/5 * * * *,cron:10010v4-cron,capture:10010v4-capture,panel:10010v4-panel
#!arguments-desc=cronexp

定时任务
默认为每 5 分钟

cron

自定义定时任务名
若设为 # 可取消定时任务

panel

自定义面板名
若设为 # 可取消面板

capture

自定义抓包脚本名
若设为 # 可取消抓包
#!format=sgmodule

[Script]
10010v4-request = type=http-request,pattern=^https?://10010v4\.com,script-path=https://github.com/ChinaTelecomOperators/ChinaUnicom/releases/download/Prerelease-Alpha/10010.js,requires-body=false,max-size=0,timeout=120

[MITM]
hostname = %APPEND% 10010v4.com, m.client.10010.com, loginxhm.10010.com
